-- Gamma 5: Gamma Rebuilds Its AI Presentation Tool With a Freeform Editor and a New Agent
-- Источник: https://gamma.app/insights/introducing-gamma-5-your-story-your-style-your-tools. Идемпотентно.

DELETE FROM news WHERE slug = 'gamma-5-launch';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('gamma-5-launch', 'en', 'tools', $t$Tools$t$, '#2dd4a0', $t$Gamma$t$, $t$https://gamma.app/insights/introducing-gamma-5-your-story-your-style-your-tools$t$, '2026-10-06', $t$Gamma 5: Gamma Rebuilds Its AI Presentation Tool With a Freeform Editor and a New Agent$t$, $t$Gamma released Gamma 5 on October 6, calling it the biggest overhaul in the company's history. The update adds a freeform canvas next to agent-led editing, a rebuilt agent that asks questions and can research the web, a wider range of visual styles, new enterprise connectors and better PowerPoint and PDF import. It is live on every plan, including Free.$t$, $t$<p>Gamma released <strong>Gamma 5</strong> on October 6, calling it "the biggest product overhaul in our company's history." The AI presentation platform says more than 100 million people have used it. The rebuild targets what Gamma calls the "AI smell": repetitive layouts, generic imagery and predictable design choices that make AI-made decks look alike.</p><h2>What changed</h2><p><strong>A freeform editor.</strong> You can now switch between agent-led editing and a fully freeform canvas, where you move, arrange and refine individual elements yourself. Prompt the agent when you want speed, take over when you want exact placement.</p><p><strong>A rebuilt agent.</strong> Before designing anything, the agent works through the idea with you in a back-and-forth and keeps context through every edit. According to Gamma's help center, in Plan mode it asks a handful of questions based on your prompt, Research mode pulls in sources from the web before writing, and during the build it writes, designs and generates images. Gamma says it uses "every frontier and image model under the hood" but does not list them.</p><p><strong>More visual styles.</strong> The style palette now runs from bold and playful to dark and moody to mid-century modern, and can be shaped around your brand.</p><p><strong>Connectors.</strong> New enterprise connectors bring existing material into a deck, for example turning a Slack thread into a presentation or a Granola call transcript into a customer pitch.</p><p><strong>Import and export.</strong> Gamma 5 imports PowerPoint files, PDFs and complex infographics with their design preserved, lets you edit individual elements and exports them again.</p><h2>Price and availability</h2><p>Gamma 5 is live for every user on every plan, and existing gammas carry over. The Free plan gives 400 credits at signup, up to 10 slides per prompt, PDF and PPTX import, and export to PDF, PPTX, PNG and Google Slides. Paid plans, billed annually, are <strong>Plus at $9</strong>, <strong>Pro at $18</strong> and <strong>Ultra at $90</strong> per seat per month, with 1,000, 4,000 and 20,000 monthly credits. Gamma says fuller memory of brand guidelines and preferences from one project to the next is coming next.</p><h2>What this means if you make presentations</h2><p><strong>If you want a first draft fast and then fine control</strong>, <a href="/tools/gamma.html">Gamma</a> now covers both: the agent builds the deck, and the freeform canvas lets you fix details by hand instead of re-prompting.</p><p><strong>If your team already has decks in PowerPoint</strong>, the improved import is the part to test first. Upload one of your own complex slides and check what survives before you move a whole library.</p><p><strong>If you are choosing between tools</strong>, compare Gamma with a design-focused alternative in <a href="/compare/gamma-vs-beautiful-ai.html">Gamma vs Beautiful.ai</a>, with a team presentation tool in <a href="/compare/gamma-vs-pitch.html">Gamma vs Pitch</a>, or with a docs-first workspace in <a href="/compare/gamma-vs-notion-ai.html">Gamma vs Notion AI</a>. The free plan is enough to try Gamma 5 on a real deck before paying.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('gamma-5-launch', 'es', 'tools', $t$Herramientas$t$, '#2dd4a0', $t$Gamma$t$, $t$https://gamma.app/insights/introducing-gamma-5-your-story-your-style-your-tools$t$, '2026-10-06', $t$Gamma 5: Gamma reconstruye su herramienta de presentaciones con IA con un editor de formato libre y un nuevo agente$t$, $t$Gamma lanzó Gamma 5 el 6 de octubre, calificándolo como la mayor renovación en la historia de la empresa. La actualización añade un lienzo de formato libre junto a la edición guiada por agente, un agente reconstruido que hace preguntas y puede investigar en la web, una gama más amplia de estilos visuales, nuevos conectores empresariales y una mejor importación de PowerPoint y PDF. Ya está disponible en todos los planes, incluido el gratuito.$t$, $t$<p>Gamma lanzó <strong>Gamma 5</strong> el 6 de octubre, calificándolo como "la mayor renovación de producto en la historia de nuestra empresa". La plataforma de presentaciones con IA afirma que más de 100 millones de personas la han usado. La reconstrucción apunta a lo que Gamma llama el "olor a IA": diseños repetitivos, imágenes genéricas y decisiones de diseño predecibles que hacen que las presentaciones hechas con IA se parezcan entre sí.</p><h2>Qué cambió</h2><p><strong>Un editor de formato libre.</strong> Ahora puedes alternar entre la edición guiada por el agente y un lienzo totalmente libre, donde mueves, organizas y perfeccionas elementos individuales tú mismo. Pídele al agente cuando quieras velocidad, y toma el control cuando quieras una ubicación exacta.</p><p><strong>Un agente reconstruido.</strong> Antes de diseñar nada, el agente trabaja la idea contigo en un ida y vuelta y mantiene el contexto a lo largo de cada edición. Según el centro de ayuda de Gamma, en el modo Plan hace un puñado de preguntas basadas en tu indicación, el modo Research incorpora fuentes de la web antes de escribir, y durante la construcción escribe, diseña y genera imágenes. Gamma dice que usa "todos los modelos de frontera y de imagen disponibles" pero no los enumera.</p><p><strong>Más estilos visuales.</strong> La paleta de estilos ahora abarca desde audaz y lúdico hasta oscuro y sombrío y moderno de mediados de siglo, y puede adaptarse a tu marca.</p><p><strong>Conectores.</strong> Nuevos conectores empresariales incorporan material existente a una presentación, por ejemplo convirtiendo un hilo de Slack en una presentación o la transcripción de una llamada de Granola en una propuesta para un cliente.</p><p><strong>Importación y exportación.</strong> Gamma 5 importa archivos de PowerPoint, PDF e infografías complejas conservando su diseño, permite editar elementos individuales y volver a exportarlos.</p><h2>Precio y disponibilidad</h2><p>Gamma 5 ya está disponible para todos los usuarios en todos los planes, y las gammas existentes se mantienen. El plan Free ofrece 400 créditos al registrarse, hasta 10 diapositivas por indicación, importación de PDF y PPTX, y exportación a PDF, PPTX, PNG y Google Slides. Los planes de pago, facturados anualmente, son <strong>Plus a $9</strong>, <strong>Pro a $18</strong> y <strong>Ultra a $90</strong> por puesto al mes, con 1,000, 4,000 y 20,000 créditos mensuales. Gamma dice que próximamente llegará una memoria más completa de las guías de marca y preferencias de un proyecto a otro.</p><h2>Qué significa esto si haces presentaciones</h2><p><strong>Si quieres un primer borrador rápido y luego control fino</strong>, <a href="/tools/gamma.html">Gamma</a> ahora cubre ambos casos: el agente construye la presentación, y el lienzo de formato libre te permite corregir detalles a mano en lugar de volver a dar indicaciones.</p><p><strong>Si tu equipo ya tiene presentaciones en PowerPoint</strong>, la importación mejorada es lo primero que hay que probar. Sube una de tus propias diapositivas complejas y comprueba qué se conserva antes de migrar toda una biblioteca.</p><p><strong>Si estás eligiendo entre herramientas</strong>, compara Gamma con una alternativa centrada en el diseño en <a href="/compare/gamma-vs-beautiful-ai.html">Gamma vs Beautiful.ai</a>, con una herramienta de presentaciones en equipo en <a href="/compare/gamma-vs-pitch.html">Gamma vs Pitch</a>, o con un espacio de trabajo centrado en documentos en <a href="/compare/gamma-vs-notion-ai.html">Gamma vs Notion AI</a>. El plan gratuito es suficiente para probar Gamma 5 en una presentación real antes de pagar.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('gamma-5-launch', 'de', 'tools', $t$Tools$t$, '#2dd4a0', $t$Gamma$t$, $t$https://gamma.app/insights/introducing-gamma-5-your-story-your-style-your-tools$t$, '2026-10-06', $t$Gamma 5: Gamma überarbeitet sein KI-Präsentationstool mit freiem Editor und neuem Agenten$t$, $t$Gamma hat am 6. Oktober Gamma 5 veröffentlicht und spricht vom größten Umbau in der Geschichte des Unternehmens. Das Update bringt eine freie Arbeitsfläche neben der agentengesteuerten Bearbeitung, einen überarbeiteten Agenten, der Rückfragen stellt und im Web recherchieren kann, eine breitere Palette an visuellen Stilen, neue Enterprise-Connectoren sowie einen verbesserten PowerPoint- und PDF-Import. Die Funktionen sind ab sofort in allen Plänen verfügbar, einschließlich des kostenlosen Plans.$t$, $t$<p>Gamma hat am 6. Oktober <strong>Gamma 5</strong> veröffentlicht und bezeichnet es als "den größten Produktumbau in der Geschichte unseres Unternehmens". Die KI-Präsentationsplattform gibt an, dass sie bereits von mehr als 100 Millionen Menschen genutzt wurde. Der Umbau zielt auf das ab, was Gamma den "AI smell" nennt: sich wiederholende Layouts, generische Bildsprache und vorhersehbare Designentscheidungen, die KI-erstellte Präsentationen einander ähneln lassen.</p><h2>Was sich ändert</h2><p><strong>Ein freier Editor.</strong> Nutzer können nun zwischen agentengesteuerter Bearbeitung und einer vollständig freien Arbeitsfläche wechseln, auf der sie einzelne Elemente selbst verschieben, anordnen und verfeinern. Der Agent wird per Prompt eingesetzt, wenn Geschwindigkeit gefragt ist, die manuelle Steuerung übernimmt man, wenn eine exakte Platzierung gewünscht ist.</p><p><strong>Ein überarbeiteter Agent.</strong> Bevor etwas gestaltet wird, bespricht der Agent die Idee im Dialog mit dem Nutzer und behält den Kontext über jede Bearbeitung hinweg bei. Laut Gammas Hilfecenter stellt der Agent im Plan-Modus anhand des Prompts einige Fragen, im Research-Modus zieht er vorab Quellen aus dem Web heran, und beim eigentlichen Erstellen schreibt, gestaltet und generiert er Bilder. Gamma erklärt, dass "jedes führende Modell und jedes Bildmodell" im Hintergrund zum Einsatz kommt, nennt die Modelle aber nicht namentlich.</p><p><strong>Mehr visuelle Stile.</strong> Die Stilpalette reicht nun von kräftig und verspielt über dunkel und stimmungsvoll bis hin zu Mid-Century-Modern-Design und lässt sich an die eigene Marke anpassen.</p><p><strong>Connectoren.</strong> Neue Enterprise-Connectoren bringen bestehendes Material in eine Präsentation ein, etwa indem sie einen Slack-Thread in eine Präsentation oder ein Granola-Anruftranskript in ein Kundenangebot verwandeln.</p><p><strong>Import und Export.</strong> Gamma 5 importiert PowerPoint-Dateien, PDFs und komplexe Infografiken unter Beibehaltung ihres Designs, erlaubt die Bearbeitung einzelner Elemente und exportiert sie anschließend erneut.</p><h2>Preis und Verfügbarkeit</h2><p>Gamma 5 steht ab sofort für alle Nutzer in allen Plänen zur Verfügung, bestehende Gammas bleiben erhalten. Der kostenlose Plan bietet bei der Anmeldung 400 Credits, bis zu 10 Folien pro Prompt, PDF- und PPTX-Import sowie Export nach PDF, PPTX, PNG und Google Slides. Die kostenpflichtigen, jährlich abgerechneten Pläne sind <strong>Plus für $9</strong>, <strong>Pro für $18</strong> und <strong>Ultra für $90</strong> pro Platz und Monat, mit 1.000, 4.000 beziehungsweise 20.000 monatlichen Credits. Gamma kündigt an, dass als Nächstes ein umfassenderes Erinnern von Markenrichtlinien und Präferenzen über Projekte hinweg folgen soll.</p><h2>Was das für Präsentationserstellende bedeutet</h2><p><strong>Wer schnell einen ersten Entwurf braucht und anschließend feine Kontrolle möchte</strong>, für den deckt <a href="/tools/gamma.html">Gamma</a> nun beides ab: Der Agent baut die Präsentation auf, und die freie Arbeitsfläche erlaubt es, Details per Hand zu korrigieren, statt erneut zu prompten.</p><p><strong>Wer im Team bereits Präsentationen in PowerPoint hat</strong>, sollte zuerst den verbesserten Import testen. Laden Sie eine Ihrer eigenen komplexen Folien hoch und prüfen Sie, was dabei erhalten bleibt, bevor Sie eine ganze Bibliothek umstellen.</p><p><strong>Wer zwischen Tools abwägt</strong>, kann Gamma mit einer designorientierten Alternative in <a href="/compare/gamma-vs-beautiful-ai.html">Gamma vs Beautiful.ai</a>, mit einem Team-Präsentationstool in <a href="/compare/gamma-vs-pitch.html">Gamma vs Pitch</a> oder mit einem dokumentenorientierten Arbeitsbereich in <a href="/compare/gamma-vs-notion-ai.html">Gamma vs Notion AI</a> vergleichen. Der kostenlose Plan reicht aus, um Gamma 5 an einer echten Präsentation auszuprobieren, bevor man bezahlt.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('gamma-5-launch', 'ru', 'tools', $t$Инструменты$t$, '#2dd4a0', $t$Gamma$t$, $t$https://gamma.app/insights/introducing-gamma-5-your-story-your-style-your-tools$t$, '2026-10-06', $t$Gamma 5: Gamma перестроила свой AI-сервис для презентаций — свободный редактор и новый агент$t$, $t$Gamma выпустила Gamma 5 6 октября и назвала её самой большой переработкой продукта за всю историю компании. В обновлении — свободный холст рядом с редактированием через агента, переписанный агент, который задаёт вопросы и умеет искать в интернете, больше визуальных стилей, новые корпоративные коннекторы и улучшенный импорт PowerPoint и PDF. Версия уже доступна на всех тарифах, включая бесплатный.$t$, $t$<p>Gamma выпустила <strong>Gamma 5</strong> 6 октября, назвав её «самой большой переработкой продукта в истории компании». По данным сервиса, им уже воспользовались более 100 миллионов человек. Главная цель обновления — избавиться от того, что в Gamma называют «запахом AI»: однотипных макетов, безликих картинок и предсказуемых дизайнерских решений, из-за которых сгенерированные презентации похожи друг на друга.</p><h2>Что изменилось</h2><p><strong>Свободный редактор.</strong> Теперь можно переключаться между правкой через агента и полностью свободным холстом, где вы сами двигаете, расставляете и дорабатываете отдельные элементы. Нужна скорость — даёте задание агенту, нужна точность — берёте управление на себя.</p><p><strong>Новый агент.</strong> Прежде чем что-то верстать, агент обсуждает с вами идею в диалоге и помнит контекст на протяжении всех правок. Как сказано в справке Gamma, в режиме Plan он задаёт несколько вопросов по вашему запросу, режим Research подтягивает источники из интернета до начала работы над текстом, а при сборке агент пишет текст, верстает и генерирует изображения. Gamma утверждает, что под капотом работают «все передовые модели для текста и изображений», но не называет их.</p><p><strong>Больше стилей.</strong> Палитра стилей теперь охватывает всё — от ярких и игривых до тёмных и атмосферных и до мид-сенчури модерна, — и её можно подстроить под ваш бренд.</p><p><strong>Коннекторы.</strong> Новые корпоративные коннекторы подтягивают в презентацию то, что у вас уже есть: например, превращают ветку в Slack в слайды или вставляют расшифровку звонка из Granola в презентацию для клиента.</p><p><strong>Импорт и экспорт.</strong> Gamma 5 импортирует файлы PowerPoint, PDF и даже сложную инфографику с сохранением дизайна, даёт править отдельные элементы и экспортирует результат обратно.</p><h2>Цены и доступность</h2><p>Gamma 5 уже работает у всех пользователей на всех тарифах, старые презентации на месте. Бесплатный тариф даёт 400 кредитов при регистрации, до 10 слайдов за один запрос, импорт PDF и PPTX и экспорт в PDF, PPTX, PNG и Google Slides. Платные тарифы при оплате за год: <strong>Plus за $9</strong>, <strong>Pro за $18</strong> и <strong>Ultra за $90</strong> за место в месяц, с 1 000, 4 000 и 20 000 кредитов в месяц соответственно. Следующим шагом Gamma обещает полноценную память: сервис будет переносить фирменный стиль и предпочтения из проекта в проект.</p><h2>Что это значит, если вы делаете презентации</h2><p><strong>Если нужен быстрый черновик, а потом точная доводка</strong>, <a href="/tools/gamma.html">Gamma</a> теперь закрывает обе задачи: агент собирает презентацию, а на свободном холсте детали можно поправить руками, не переписывая запрос.</p><p><strong>Если у команды уже есть презентации в PowerPoint</strong>, первым делом проверьте улучшенный импорт. Загрузите один из своих самых сложных слайдов и посмотрите, что сохранилось, прежде чем переносить всю библиотеку.</p><p><strong>Если вы выбираете между сервисами</strong>, сравните Gamma с инструментом, сильным в дизайне, — <a href="/compare/gamma-vs-beautiful-ai.html">Gamma vs Beautiful.ai</a>, с сервисом для командных презентаций — <a href="/compare/gamma-vs-pitch.html">Gamma vs Pitch</a>, или с рабочим пространством для документов — <a href="/compare/gamma-vs-notion-ai.html">Gamma vs Notion AI</a>. Чтобы попробовать Gamma 5 на настоящей презентации, хватит и бесплатного тарифа.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('gamma-5-launch', 'ua', 'tools', $t$Інструменти$t$, '#2dd4a0', $t$Gamma$t$, $t$https://gamma.app/insights/introducing-gamma-5-your-story-your-style-your-tools$t$, '2026-10-06', $t$Gamma 5: компанія Gamma переробляє свій ШІ-інструмент для презентацій, додавши вільний редактор і нового агента$t$, $t$Gamma випустила Gamma 5 6 жовтня, назвавши це найбільшим оновленням в історії компанії. Нова версія додає вільне полотно поруч із редагуванням за допомогою агента, переробленого агента, який ставить запитання і може шукати інформацію в інтернеті, ширший вибір візуальних стилів, нові корпоративні конектори та покращений імпорт PowerPoint і PDF. Оновлення доступне на всіх тарифах, включно з безкоштовним.$t$, $t$<p>Gamma випустила <strong>Gamma 5</strong> 6 жовтня, назвавши це "найбільшим оновленням продукту в історії нашої компанії". Платформа для створення презентацій на основі ШІ повідомляє, що нею скористалися понад 100 мільйонів людей. Переробка націлена на те, що Gamma називає "запахом ШІ" — повторювані макети, типові зображення та передбачувані дизайнерські рішення, через які створені ШІ презентації виглядають однаково.</p><h2>Що змінилося</h2><p><strong>Вільний редактор.</strong> Тепер можна перемикатися між редагуванням за допомогою агента і повністю вільним полотном, де ви самі переміщуєте, розташовуєте й доопрацьовуєте окремі елементи. Звертайтеся до агента, коли потрібна швидкість, і беріть керування на себе, коли потрібне точне розташування.</p><p><strong>Перероблений агент.</strong> Перш ніж щось проєктувати, агент обговорює з вами ідею в режимі діалогу і зберігає контекст протягом усього редагування. Згідно з довідковим центром Gamma, у режимі Plan він ставить кілька запитань на основі вашого запиту, режим Research підбирає джерела з інтернету перед написанням тексту, а під час створення презентації він пише текст, розробляє дизайн і генерує зображення. Gamma повідомляє, що використовує "усі передові моделі та моделі для генерації зображень", але не наводить їхній перелік.</p><p><strong>Більше візуальних стилів.</strong> Палітра стилів тепер охоплює від сміливого й грайливого до темного й похмурого та стилю середини століття, і може підлаштовуватися під ваш бренд.</p><p><strong>Конектори.</strong> Нові корпоративні конектори дозволяють переносити наявні матеріали в презентацію, наприклад перетворювати тред у Slack на презентацію або розшифровку дзвінка з Granola — на пропозицію для клієнта.</p><p><strong>Імпорт та експорт.</strong> Gamma 5 імпортує файли PowerPoint, PDF та складні інфографіки зі збереженням їхнього дизайну, дозволяє редагувати окремі елементи й знову експортувати їх.</p><h2>Ціна та доступність</h2><p>Gamma 5 доступна кожному користувачу на всіх тарифах, а наявні презентації переносяться автоматично. Безкоштовний тариф дає 400 кредитів при реєстрації, до 10 слайдів на запит, імпорт PDF і PPTX та експорт у PDF, PPTX, PNG і Google Slides. Платні тарифи з щорічною оплатою — це <strong>Plus за $9</strong>, <strong>Pro за $18</strong> і <strong>Ultra за $90</strong> за місце на місяць, з 1000, 4000 і 20 000 кредитів на місяць відповідно. Gamma повідомляє, що найближчим часом планує додати повніше збереження пам'яті про фірмовий стиль і вподобання від проєкту до проєкту.</p><h2>Що це означає, якщо ви створюєте презентації</h2><p><strong>Якщо вам потрібен швидкий перший варіант, а потім тонке налаштування</strong>, <a href="/tools/gamma.html">Gamma</a> тепер охоплює обидва сценарії: агент створює презентацію, а вільне полотно дозволяє виправляти деталі вручну замість повторних запитів.</p><p><strong>Якщо ваша команда вже має презентації у PowerPoint</strong>, покращений імпорт — це те, що варто перевірити в першу чергу. Завантажте один зі своїх складних слайдів і перевірте, що збережеться, перш ніж переносити всю бібліотеку.</p><p><strong>Якщо ви обираєте між інструментами</strong>, порівняйте Gamma з орієнтованою на дизайн альтернативою в матеріалі <a href="/compare/gamma-vs-beautiful-ai.html">Gamma vs Beautiful.ai</a>, з інструментом для командних презентацій у <a href="/compare/gamma-vs-pitch.html">Gamma vs Pitch</a>, або з робочим простором, орієнтованим на документи, у <a href="/compare/gamma-vs-notion-ai.html">Gamma vs Notion AI</a>. Безкоштовного тарифу достатньо, щоб спробувати Gamma 5 на реальній презентації, перш ніж платити.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('gamma-5-launch', 'he', 'tools', $t$כלים$t$, '#2dd4a0', $t$Gamma$t$, $t$https://gamma.app/insights/introducing-gamma-5-your-story-your-style-your-tools$t$, '2026-10-06', $t$Gamma 5: גמא בונה מחדש את כלי מצגות הבינה המלאכותית שלה עם עורך חופשי וסוכן חדש$t$, $t$גמא השיקה ב-6 באוקטובר את Gamma 5, והגדירה אותה כשדרוג הגדול ביותר בתולדות החברה. העדכון מוסיף קנבס חופשי לצד עריכה מונחית-סוכן, סוכן מחודש ששואל שאלות ויכול לחקור באינטרנט, מגוון רחב יותר של סגנונות עיצוביים, מחברים (connectors) חדשים לארגונים וייבוא משופר של קבצי PowerPoint ו-PDF. העדכון זמין בכל התוכניות, כולל התוכנית החינמית.$t$, $t$<p>גמא השיקה ב-6 באוקטובר את <strong>Gamma 5</strong>, והגדירה אותה כ"שדרוג המוצר הגדול ביותר בתולדות החברה שלנו". פלטפורמת המצגות מבוססת הבינה המלאכותית מציינת כי יותר מ-100 מיליון אנשים השתמשו בה. הבנייה מחדש מכוונת למה שגמא מכנה "ריח הבינה המלאכותית": פריסות חוזרות ונשנות, דימויים גנריים ובחירות עיצוביות צפויות שגורמות למצגות שנוצרו על ידי בינה מלאכותית להיראות דומות.</p><h2>מה השתנה</h2><p><strong>עורך חופשי.</strong> כעת ניתן לעבור בין עריכה מונחית-סוכן לבין קנבס חופשי לחלוטין, שבו מזיזים, מסדרים ומעדנים אלמנטים בודדים בעצמכם. ניתן להנחות את הסוכן כשרוצים מהירות, ולקחת שליטה כשרוצים מיקום מדויק.</p><p><strong>סוכן מחודש.</strong> לפני עיצוב כל דבר, הסוכן עובר יחד איתכם על הרעיון בדו-שיח ושומר על ההקשר לאורך כל עריכה. לפי מרכז העזרה של גמא, במצב Plan הוא שואל כמה שאלות בהתבסס על ההנחיה שלכם, מצב Research מביא מקורות מהאינטרנט לפני הכתיבה, ובמהלך הבנייה הוא כותב, מעצב ומייצר תמונות. גמא מציינת כי היא משתמשת ב"כל מודל חזית ומודל תמונה מתקדם מתחת למכסה המנוע", אך אינה מפרטת אילו.</p><p><strong>יותר סגנונות עיצוביים.</strong> לוח הסגנונות נע כעת מנועז ושובב דרך כהה ואפל ועד מודרני אמצע-המאה, וניתן לעצב אותו בהתאם למותג שלכם.</p><p><strong>מחברים (Connectors).</strong> מחברים חדשים לארגונים מביאים חומר קיים אל תוך מצגת, לדוגמה הפיכת שרשור בסלאק (Slack) למצגת או תמלול שיחה מ-Granola למצגת מכירה ללקוח.</p><p><strong>ייבוא וייצוא.</strong> Gamma 5 מייבאת קבצי PowerPoint, PDF ואינפוגרפיקות מורכבות תוך שמירה על העיצוב שלהן, מאפשרת לערוך אלמנטים בודדים ולייצא אותם מחדש.</p><h2>מחיר וזמינות</h2><p>Gamma 5 זמינה לכל משתמש בכל תוכנית, וגמות קיימות עוברות אוטומטית לגרסה החדשה. התוכנית החינמית מעניקה 400 קרדיטים בהרשמה, עד 10 שקופיות להנחיה, ייבוא PDF ו-PPTX, וייצוא ל-PDF, PPTX, PNG ול-Google Slides. התוכניות בתשלום, בחיוב שנתי, הן <strong>Plus במחיר 9$</strong>, <strong>Pro במחיר 18$</strong> ו-<strong>Ultra במחיר 90$</strong> למשתמש לחודש, עם 1,000, 4,000 ו-20,000 קרדיטים חודשיים בהתאמה. גמא מציינת כי בקרוב תתווסף זיכרון מלא יותר של הנחיות מותג והעדפות ממיזם אחד למשנהו.</p><h2>מה המשמעות עבור מי שיוצר מצגות</h2><p><strong>אם אתם רוצים טיוטה ראשונה מהירה ולאחר מכן שליטה מדויקת</strong>, <a href="/tools/gamma.html">Gamma</a> מכסה כעת את שני הצרכים: הסוכן בונה את המצגת, והקנבס החופשי מאפשר לתקן פרטים באופן ידני במקום לנסח הנחיה מחדש.</p><p><strong>אם לצוות שלכם כבר יש מצגות ב-PowerPoint</strong>, הייבוא המשופר הוא החלק שכדאי לבדוק ראשון. העלו אחת מהשקופיות המורכבות שלכם ובדקו מה נשמר לפני שתעבירו ספרייה שלמה.</p><p><strong>אם אתם בוחרים בין כלים</strong>, השוו בין Gamma לחלופה המתמקדת בעיצוב במאמר <a href="/compare/gamma-vs-beautiful-ai.html">Gamma vs Beautiful.ai</a>, לכלי מצגות צוותי במאמר <a href="/compare/gamma-vs-pitch.html">Gamma vs Pitch</a>, או לסביבת עבודה מבוססת-מסמכים במאמר <a href="/compare/gamma-vs-notion-ai.html">Gamma vs Notion AI</a>. התוכנית החינמית מספיקה כדי לנסות את Gamma 5 על מצגת אמיתית לפני התשלום.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('gamma-5-launch', 'fr', 'tools', $t$Outils$t$, '#2dd4a0', $t$Gamma$t$, $t$https://gamma.app/insights/introducing-gamma-5-your-story-your-style-your-tools$t$, '2026-10-06', $t$Gamma 5 : Gamma refond son outil de présentation IA avec un éditeur en mode libre et un nouvel agent$t$, $t$Gamma a lancé Gamma 5 le 6 octobre, qualifiant cette mise à jour de la plus grande refonte de l'histoire de l'entreprise. Elle ajoute un canevas en mode libre en complément de l'édition pilotée par agent, un agent repensé capable de poser des questions et de faire des recherches sur le web, un éventail plus large de styles visuels, de nouveaux connecteurs pour les entreprises, ainsi qu'une importation améliorée de PowerPoint et de PDF. Elle est disponible sur toutes les formules, y compris la version gratuite.$t$, $t$<p>Gamma a lancé <strong>Gamma 5</strong> le 6 octobre, la qualifiant de "plus grande refonte de produit dans l'histoire de notre entreprise". La plateforme de présentation IA affirme avoir été utilisée par plus de 100 millions de personnes. Cette refonte cible ce que Gamma appelle l'« odeur de l'IA » : des mises en page répétitives, des images génériques et des choix de design prévisibles qui font que les diaporamas créés par IA se ressemblent tous.</p><h2>Ce qui change</h2><p><strong>Un éditeur en mode libre.</strong> Il est désormais possible de basculer entre l'édition pilotée par agent et un canevas entièrement libre, où l'on déplace, organise et affine soi-même chaque élément. On sollicite l'agent pour aller vite, et on reprend la main pour un placement précis.</p><p><strong>Un agent repensé.</strong> Avant de concevoir quoi que ce soit, l'agent échange avec l'utilisateur pour affiner l'idée et conserve le contexte à chaque modification. Selon le centre d'aide de Gamma, en mode Plan, il pose quelques questions basées sur la requête initiale ; en mode Research, il va chercher des sources sur le web avant de rédiger ; et pendant la construction, il rédige, conçoit et génère des images. Gamma indique utiliser "tous les modèles de pointe et modèles d'image disponibles" sans en préciser la liste.</p><p><strong>Davantage de styles visuels.</strong> La palette de styles s'étend désormais du ton audacieux et ludique au sombre et feutré, en passant par le mid-century modern, et peut être adaptée à l'identité de marque.</p><p><strong>Connecteurs.</strong> De nouveaux connecteurs pour les entreprises permettent d'intégrer des contenus existants dans un diaporama, par exemple en transformant un fil de discussion Slack en présentation ou une transcription d'appel Granola en argumentaire client.</p><p><strong>Importation et exportation.</strong> Gamma 5 importe des fichiers PowerPoint, des PDF et des infographies complexes en conservant leur mise en forme, permet de modifier chaque élément individuellement, puis de les exporter à nouveau.</p><h2>Prix et disponibilité</h2><p>Gamma 5 est disponible pour tous les utilisateurs, sur toutes les formules, et les présentations existantes sont conservées. La formule gratuite offre 400 crédits à l'inscription, jusqu'à 10 diapositives par requête, l'importation de PDF et PPTX, ainsi que l'exportation vers PDF, PPTX, PNG et Google Slides. Les formules payantes, facturées annuellement, sont <strong>Plus à 9 $</strong>, <strong>Pro à 18 $</strong> et <strong>Ultra à 90 $</strong> par utilisateur et par mois, avec respectivement 1 000, 4 000 et 20 000 crédits mensuels. Gamma annonce qu'une mémoire plus complète des directives de marque et des préférences, d'un projet à l'autre, arrivera prochainement.</p><h2>Ce que cela signifie pour ceux qui créent des présentations</h2><p><strong>Si vous voulez un premier jet rapide puis un contrôle précis</strong>, <a href="/tools/gamma.html">Gamma</a> couvre désormais les deux besoins : l'agent construit le diaporama, et le canevas en mode libre permet de corriger les détails à la main plutôt que de reformuler une requête.</p><p><strong>Si votre équipe dispose déjà de diaporamas sous PowerPoint</strong>, l'importation améliorée est la fonctionnalité à tester en priorité. Importez l'une de vos diapositives complexes et vérifiez ce qui est conservé avant de migrer toute une bibliothèque.</p><p><strong>Si vous hésitez entre plusieurs outils</strong>, comparez Gamma avec une alternative axée sur le design dans <a href="/compare/gamma-vs-beautiful-ai.html">Gamma vs Beautiful.ai</a>, avec un outil de présentation pensé pour les équipes dans <a href="/compare/gamma-vs-pitch.html">Gamma vs Pitch</a>, ou avec un espace de travail centré sur les documents dans <a href="/compare/gamma-vs-notion-ai.html">Gamma vs Notion AI</a>. La formule gratuite suffit pour essayer Gamma 5 sur un véritable diaporama avant de payer.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('gamma-5-launch', 'pt', 'tools', $t$Ferramentas$t$, '#2dd4a0', $t$Gamma$t$, $t$https://gamma.app/insights/introducing-gamma-5-your-story-your-style-your-tools$t$, '2026-10-06', $t$Gamma 5: Gamma reconstrói sua ferramenta de apresentações com IA com editor de formato livre e novo agente$t$, $t$A Gamma lançou o Gamma 5 em 6 de outubro, chamando-o de a maior reformulação da história da empresa. A atualização adiciona um canvas de formato livre ao lado da edição guiada por agente, um agente reconstruído que faz perguntas e pode pesquisar na web, uma gama mais ampla de estilos visuais, novos conectores empresariais e melhor importação de PowerPoint e PDF. Já está disponível em todos os planos, incluindo o Free.$t$, $t$<p>A Gamma lançou o <strong>Gamma 5</strong> em 6 de outubro, chamando-o de "a maior reformulação de produto na história da nossa empresa". A plataforma de apresentações com IA afirma que mais de 100 milhões de pessoas já a utilizaram. A reconstrução tem como alvo o que a Gamma chama de "cheiro de IA": layouts repetitivos, imagens genéricas e escolhas de design previsíveis que fazem as apresentações feitas por IA parecerem todas iguais.</p><h2>O que mudou</h2><p><strong>Um editor de formato livre.</strong> Agora é possível alternar entre a edição guiada por agente e um canvas totalmente de formato livre, no qual você move, organiza e refina elementos individuais por conta própria. Use o agente quando quiser rapidez, assuma o controle quando quiser posicionamento exato.</p><p><strong>Um agente reconstruído.</strong> Antes de projetar qualquer coisa, o agente discute a ideia com você em um vai e vem e mantém o contexto ao longo de cada edição. De acordo com a central de ajuda da Gamma, no modo Plan ele faz algumas perguntas com base no seu prompt, o modo Research busca fontes na web antes de escrever, e durante a construção ele escreve, projeta e gera imagens. A Gamma afirma usar "todo modelo de fronteira e modelo de imagem por trás dos panos", mas não os lista.</p><p><strong>Mais estilos visuais.</strong> A paleta de estilos agora vai de ousado e divertido a escuro e sombrio e a moderno de meados do século, e pode ser moldada de acordo com a sua marca.</p><p><strong>Conectores.</strong> Novos conectores empresariais trazem material já existente para uma apresentação, por exemplo transformando uma thread do Slack em uma apresentação ou a transcrição de uma chamada do Granola em um pitch para cliente.</p><p><strong>Importação e exportação.</strong> O Gamma 5 importa arquivos do PowerPoint, PDFs e infográficos complexos com o design preservado, permite editar elementos individuais e exportá-los novamente.</p><h2>Preço e disponibilidade</h2><p>O Gamma 5 já está disponível para todos os usuários em todos os planos, e as gammas existentes são mantidas. O plano Free oferece 400 créditos no cadastro, até 10 slides por prompt, importação de PDF e PPTX, e exportação para PDF, PPTX, PNG e Google Slides. Os planos pagos, cobrados anualmente, são <strong>Plus a $9</strong>, <strong>Pro a $18</strong> e <strong>Ultra a $90</strong> por usuário por mês, com 1.000, 4.000 e 20.000 créditos mensais. A Gamma afirma que uma memória mais completa das diretrizes de marca e preferências de um projeto para o outro está a caminho.</p><h2>O que isso significa para quem cria apresentações</h2><p><strong>Se você quer um primeiro rascunho rápido e depois controle fino</strong>, o <a href="/tools/gamma.html">Gamma</a> agora cobre as duas pontas: o agente constrói a apresentação, e o canvas de formato livre permite corrigir detalhes manualmente em vez de refazer o prompt.</p><p><strong>Se sua equipe já tem apresentações em PowerPoint</strong>, a importação aprimorada é a primeira coisa a testar. Carregue um dos seus próprios slides complexos e verifique o que se mantém antes de migrar uma biblioteca inteira.</p><p><strong>Se você está escolhendo entre ferramentas</strong>, compare o Gamma com uma alternativa focada em design em <a href="/compare/gamma-vs-beautiful-ai.html">Gamma vs Beautiful.ai</a>, com uma ferramenta de apresentações para equipes em <a href="/compare/gamma-vs-pitch.html">Gamma vs Pitch</a>, ou com um espaço de trabalho centrado em documentos em <a href="/compare/gamma-vs-notion-ai.html">Gamma vs Notion AI</a>. O plano gratuito já é suficiente para experimentar o Gamma 5 em uma apresentação real antes de pagar.</p>$t$, NULL, true);
